 .ckb-b button{flex:1 1 calc(50% - 4px);min-height:44px;font-size:14px;padding:0 8px}.ckb-b button.ckb-s{flex:1 1 100%;border:0;background:none;min-height:44px;text-decoration:underline;text-underline-offset:3px;font-weight:500}.ckb-b button.ckb-s.ckb-k{background:#131314;color:#fff;text-decoration:none;border:1.5px solid #131314;font-weight:600}}
