.kz .kzbtn.p{background:var(--kz-pink);border-color:var(--kz-pink);color:#fff;box-shadow:0 8px 28px rgba(208,52,95,.25)}.kz .kzbtn.p:hover{background:#b8264f;border-color:#b8264f}
