.kz .kzhero{padding:64px 0 56px}.kz .kzhero h1{font:600 clamp(38px,5.4vw,72px)/1.03 var(--fd,Jost,system-ui);letter-spacing:-.02em;margin:0 0 18px;max-width:900px}
