.kz .kzchips .kzw{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none}.kz .kzchips a{flex:none;min-height:44px;display:inline-flex;align-items:center;padding:0 16px;border:1px solid var(--kz-line);border-radius:999px;background:#fff;color:var(--kz-ink);font:600 14.5px var(--fb,system-ui);text-decoration:none}
