.kz .kzsteps div{padding:24px;border:1px solid rgba(255,255,255,.18);border-radius:14px}.kz .kzsteps b{display:block;font:600 22px var(--fd,Jost);color:#fff;margin:10px 0 6px}.kz .kzsteps span{font:600 13px var(--fm,monospace);color:#e8456e}
/* Kariyer */
