.kz .kzvals div{padding:24px;border:1px solid var(--kz-line);border-radius:14px;background:#fff}
.kz .kzfl{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 22px}.kz .kzfl button{min-height:44px;padding:0 16px;border:1px solid var(--kz-line);background:#fff;border-radius:999px;font:600 14.5px var(--fb,system-ui);cursor:pointer;color:var(--kz-ink)}
