.kz dialog.kzdlg{margin:auto;inset:0;position:fixed;width:min(560px,calc(100vw - 24px));max-height:calc(100vh - 24px);border:0;border-radius:16px;padding:0;overflow:auto;box-shadow:0 30px 80px -20px rgba(8,14,25,.55);color:var(--kz-ink)}
